    // state, timeout event, milliseconds
    inline const Washer::TimerRow Washer::kTimers[Washer::kTimerCount] = {
        { State::Washing, Event::Washing_After30000ms, 30000u },
        { State::Rinsing, Event::Rinsing_After20000ms, 20000u },
    };

    // source, event, guard, negate guard, action, target, least common ancestor, trace name
    inline const Washer::TransitionRow Washer::kTransitions[13] = {
        { State::Idle, Event::Start, nullptr, false, &Washer::fillWater, State::Running, State::None, "Idle -> Running" },
        { State::Idle, Event::QuickRinse, nullptr, false, nullptr, State::Rinsing, State::None, "Idle -> Rinsing" },
        { State::Running, Event::Completion, nullptr, false, &Washer::beep, State::Idle, State::None, "Running -> Idle" },
        { State::Running, Event::Cancel, nullptr, false, &Washer::drain, State::Idle, State::None, "Running -> Idle" },
        { State::Washing, Event::Washing_After30000ms, nullptr, false, &Washer::drain, State::Rinsing, State::Running, "Washing -> Rinsing" },
        { State::Rinsing, Event::Rinsing_After20000ms, nullptr, false, nullptr, State::Spinning, State::Running, "Rinsing -> Spinning" },
        { State::Spinning, Event::Spun, nullptr, false, nullptr, State::ProgramDone, State::Running, "Spinning -> ProgramDone" },
        { State::Heating, Event::TempReached, nullptr, false, nullptr, State::Holding, State::Running, "Heating -> Holding" },
        { State::Heating, Event::Overheat, nullptr, false, nullptr, State::Error, State::None, "Heating -> Error" },
        { State::Holding, Event::TempDropped, nullptr, false, nullptr, State::Heating, State::Running, "Holding -> Heating" },
        { State::Holding, Event::Spun, nullptr, false, nullptr, State::HeaterDone, State::Running, "Holding -> HeaterDone" },
        { State::Holding, Event::SetTemp, nullptr, false, &Washer::Transition_11, State::None, State::Running, "Holding (internal)" },
        { State::Error, Event::Reset, &Washer::isCool, false, nullptr, State::Idle, State::None, "Error -> Idle" },
    };

